import { SQSClient, ReceiveMessageCommand, DeleteMessageBatchCommand, SendMessageCommand } from '@aws-sdk/client-sqs';

export const handler = async () => {
  const dlq = new SQSClient({ region: 'us-east-1' });
  const mainQueue = new SQSClient({ region: 'us-east-1' });

  const received = await dlq.send(new ReceiveMessageCommand({
    QueueUrl: process.env.DLQ_URL!,
    MaxNumberOfMessages: 10,
    WaitTimeSeconds: 5
  }));

  for (const msg of received.Messages ?? []) {
    const body = JSON.parse(msg.Body!);

    // Transform: fix known issues
    if (!body.customerId) body.customerId = 'UNKNOWN';
    if (body.amount < 0) body.amount = Math.abs(body.amount);

    // Replay to main queue with idempotency key
    await mainQueue.send(new SendMessageCommand({
      QueueUrl: process.env.MAIN_QUEUE_URL!,
      MessageBody: JSON.stringify(body),
      MessageDeduplicationId: msg.MessageId
    }));

    // Delete from DLQ after successful replay
    await dlq.send(new DeleteMessageBatchCommand({
      QueueUrl: process.env.DLQ_URL!,
      Entries: [{ Id: msg.MessageId!, ReceiptHandle: msg.ReceiptHandle! }]
    }));

    console.log(`Replayed message ${msg.MessageId}`);
  }
};

public class DlqReplayService : BackgroundService
{
    private readonly IModel _dlqChannel;
    private readonly IModel _mainChannel;
    private readonly ILogger<DlqReplayService> _logger;

    public DlqReplayService(IConnection connection, ILogger<DlqReplayService> logger)
    {
        _dlqChannel = connection.CreateModel();
        _mainChannel = connection.CreateModel();
        _logger = logger;
    }

    protected override Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _dlqChannel.BasicConsume(queue: "orders.dlq", autoAck: false, consumer: new EventingBasicConsumer(_dlqChannel)
        {
            Received += async (sender, ea) =>
            {
                var body = ea.Body.ToArray();
                var message = JsonSerializer.Deserialize<OrderMessage>(body)!;

                // Transform known bad data
                if (string.IsNullOrEmpty(message.CustomerId))
                    message.CustomerId = "UNKNOWN";

                // Publish to main exchange with original correlation id
                var props = _mainChannel.CreateBasicProperties();
                props.MessageId = ea.BasicProperties.MessageId;
                props.CorrelationId = ea.BasicProperties.CorrelationId;

                _mainChannel.BasicPublish(
                    exchange: "orders-exchange",
                    routingKey: "orders.created",
                    basicProperties: props,
                    body: JsonSerializer.SerializeToUtf8Bytes(message));

                _dlqChannel.BasicAck(ea.DeliveryTag, multiple: false);
                _logger.LogInformation("Replayed message {MessageId}", props.MessageId);
            }
        });

        return Task.CompletedTask;
    }
}
